{
  "operationName": "RegisterUser",
  "query": "mutation RegisterUser($username: String!, $email: String!, $password: String!) { register(username: $username, email: $email, password: $password) { success message } }",
  "variables": {
    "username": "testuser",
    "email": "test@test.com",
    "password": "Test@123"
  }
}

{
  "operationName": "Login",
  "query": "mutation Login($username: String!, $password: String!, $platform: String!, $deviceName: String!) { login(username: $username, password: $password, platform: $platform, deviceName: $deviceName) { success accessToken refreshToken user { id username } } }",
  "variables": {
    "username": "testuser",
    "password": "Test@123",
    "platform": "web",
    "deviceName": "Postman"
  }
}

{
  "operationName": "GetMe",
  "query": "query GetMe { me { id username email emailVerified dateJoined } }"
}

{
  "operationName": "RefreshToken",
  "query": "mutation RefreshToken($refreshToken: String!, $platform: String!) { refreshToken(refreshToken: $refreshToken, platform: $platform) { success accessToken refreshToken } }",
  "variables": {
    "refreshToken": "{{refreshToken}}",
    "platform": "web"
  }
}

{
  "operationName": "ChangePassword",
  "query": "mutation ChangePassword($oldPassword: String!, $newPassword: String!) { changePassword(oldPassword: $oldPassword, newPassword: $newPassword) { success message } }",
  "variables": {
    "oldPassword": "Test@123",
    "newPassword": "NewPass@123"
  }
}

{
  "operationName": "CreateUpload",
  "query": "mutation CreateUpload($title: String!, $description: String!) { createUpload(title: $title, description: $description) { success message upload { id title createdAt } } }",
  "variables": {
    "title": "My First Blog",
    "description": "Hello World"
  }
}

{
  "operationName": "GetAllUploads",
  "query": "query GetAllUploads { allUploads { id title description images createdAt } }"
}
